function u(r){if(typeof r=="number")return Math.abs(r);if(r&&typeof r=="object"){if("z"in r){let t=r;return Math.sqrt(t.x*t.x+t.y*t.y+t.z*t.z)}if("r"in r){let t=r;return Math.sqrt(t.r*t.r+t.g*t.g+t.b*t.b+t.a*t.a)}if("x"in r){let t=r;return Math.sqrt(t.x*t.x+t.y*t.y)}}return 0}var o={build(r,t){let e=t.input(r,"input"),n=i=>u(e(i));t.setOutput(r.id,"output",n)}};export{o as particleVectorLengthBlock};
